@import "tailwindcss";

@theme {
    --frobnicate-small: 2px;
    --frobnicate-large: 9px;
}

@utility synthetic-static {
    display: grid;
    opacity: 0.5;
}

@utility synthetic-fn-* {
    margin: --value(--frobnicate-*, [length]);
}

